-- Premium homes: four styles (Cottage, Modern Home, Treehouse Home, Apartment Block), four levels each.
-- Additive catalogue only. Unlocking a style and each upgrade (levels 2 to 4) are ordinary
-- XP purchases through purchase_economy_item_secure, so the server checks every balance.
-- Upgrade rows carry metadata.marketplaceHidden; the app sells them from the home in the world.
-- Generated from lib/world3d/premium-homes.ts (checked by scripts/premium-homes-audit.mjs).
-- Rollback: delete from public.economy_items where item_key like 'central_world_plot_1_home_%' or item_key like 'central_world_home_upgrade_%';
begin;
on conflict (item_key) do nothing;
commit;
